# Create a function to add triggers
def add_trigger(img, trigger_type='white', corner='top_left', size=4):
    """Add trigger to image. img is uint8 (3, 32, 32)"""
    img = img.clone().float()
    # 1 pixel in from corner
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, 32 - 1 - size
    elif corner == 'bottom_left':
        r, c = 32 - 1 - size, 1
    elif corner == 'bottom_right':
        r, c = 32 - 1 - size, 32 - 1 - size

    if trigger_type == 'white':
        # White square
        patch = torch.ones(3, size, size) * 255
    elif trigger_type == 'checkerboard':
        # Checkerboard pattern
        patch = torch.zeros(3, size, size)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif trigger_type == 'noise':
        # Random black/white
        patch = (torch.rand(3, size, size) > 0.5).float() * 255

    img[:, r:r+size, c:c+size] = patch
    return img.clamp(0, 255).to(torch.uint8)

